// ============================================================
// Customer Support Knowledge Base (sample data for testing)
// ============================================================
const kb = [
  {
    category: 'billing',
    title: 'How to update payment method',
    content: 'To update your payment method, log into your account and navigate to Settings > Billing > Payment Methods. Click "Add New Payment Method" and enter your card details. The new method will be active immediately. You can also remove old cards from the same screen.'
  },
  {
    category: 'billing',
    title: 'Refund policy',
    content: 'We offer a 30-day money-back guarantee on all subscriptions. To request a refund, contact support within 30 days of purchase. Refunds are processed within 5 to 7 business days and returned to the original payment method.'
  },
  {
    category: 'billing',
    title: 'Cancel subscription',
    content: 'Cancel your subscription anytime from Settings > Billing > Subscription. Cancellation takes effect at the end of the current billing cycle. You retain full access until then. No cancellation fees apply.'
  },
  {
    category: 'billing',
    title: 'Pricing plans and tiers',
    content: 'We offer three plans: Free (basic features, 100 API requests/hour), Pro ($29/month, 1000 requests/hour, priority support), and Enterprise (custom pricing, unlimited requests, dedicated manager). Annual billing saves 20 percent.'
  },
  {
    category: 'technical',
    title: 'Application crashes on startup',
    content: 'If the application crashes on startup: 1) Clear browser cache and cookies, 2) Update to the latest version, 3) Restart your device, 4) Try a different browser, 5) Reinstall if desktop app. If the problem persists, collect crash logs from Settings > Diagnostics and contact support.'
  },
  {
    category: 'technical',
    title: 'Slow performance issues',
    content: 'For slow performance: check your internet connection speed, close unnecessary browser tabs, disable browser extensions, clear the cache, and try incognito mode. If the application is slow only in our platform, it may be a server-side issue, please contact support.'
  },
  {
    category: 'technical',
    title: 'API rate limits and errors',
    content: 'API rate limits by plan: Free tier 100 requests/hour, Pro 1000 requests/hour, Enterprise unlimited. Rate limits reset at the top of every hour. Exceeding limits returns HTTP 429 status code. Use exponential backoff for retries.'
  },
  {
    category: 'technical',
    title: 'Integration not syncing',
    content: 'If your integration is not syncing: verify API credentials are correct, check permissions scope, ensure webhooks are not disabled, review logs in Settings > Integrations > Activity. Re-authenticate if tokens expired.'
  },
  {
    category: 'account',
    title: 'Reset password',
    content: 'To reset your password, click "Forgot Password" on the login page and enter your email address. You will receive a reset link within 5 minutes. The link is valid for 1 hour. Check spam folder if not received.'
  },
  {
    category: 'account',
    title: 'Delete account permanently',
    content: 'To delete your account go to Settings > Account > Delete Account. Enter your password to confirm. Account deletion is permanent and irreversible. All your data including projects, files, and history will be removed within 30 days as per GDPR.'
  },
  {
    category: 'account',
    title: 'Two-factor authentication setup',
    content: 'Enable 2FA under Settings > Security > Two-Factor Authentication. Scan the QR code with an authenticator app like Google Authenticator or Authy. Save the backup codes in a secure location. You can also use SMS but app-based is more secure.'
  },
  {
    category: 'account',
    title: 'Change email address',
    content: 'To change your email address, go to Settings > Account > Email. Enter the new email and your current password. A verification link will be sent to the new address. The change takes effect after verification.'
  },
  {
    category: 'general',
    title: 'Business hours and support availability',
    content: 'Our support team is available Sunday to Thursday, 9 AM to 6 PM Cairo time (EET). Email support responses within 24 hours for standard tier, 4 hours for Pro, and 1 hour for Enterprise. Live chat available during business hours.'
  },
  {
    category: 'general',
    title: 'Data privacy and security',
    content: 'We are GDPR and SOC 2 compliant. All data is encrypted in transit using TLS 1.3 and at rest using AES-256. We do not sell user data. You can export or delete your data anytime from Settings > Privacy. Read our full privacy policy at our website.'
  },
  {
    category: 'general',
    title: 'Feature request process',
    content: 'Submit feature requests through Settings > Feedback > Feature Request, or our public roadmap board. Our product team reviews requests weekly. Popular requests are prioritized. We announce new features in our monthly newsletter and changelog.'
  }
];

return kb.map((item, idx) => ({
  json: {
    id: 'kb_' + (idx + 1),
    category: item.category,
    title: item.title,
    text: 'Category: ' + item.category + '\nTitle: ' + item.title + '\n\n' + item.content
  }
}));

// ============================================================
// Classify customer issue into category + priority
// Input: issue description string (via `query` variable)
// Output: JSON with category, priority, reasoning
// ============================================================
const issue = String(query || '').toLowerCase();

let category = 'general';
let priority = 'medium';

// Category detection by keyword patterns
if (/(payment|invoice|bill|charge|refund|subscription|price|pricing|cost|credit card|money|paid|pay|discount|plan)/i.test(issue)) {
  category = 'billing';
} else if (/(error|bug|crash|not working|broken|fail|issue|problem|slow|lag|freeze|500|404|api|endpoint|request|timeout|integration)/i.test(issue)) {
  category = 'technical';
} else if (/(login|password|account|access|username|reset|signup|register|2fa|authentication|email|delete|sign in|sign up)/i.test(issue)) {
  category = 'account';
}

// Priority detection
if (/(urgent|critical|asap|emergency|down|outage|severe|immediately|cannot|can't work|losing money|data loss|production)/i.test(issue)) {
  priority = 'high';
} else if (/(minor|small|little|whenever|slight|suggestion|feature request|nice to have|enhancement)/i.test(issue)) {
  priority = 'low';
}

return JSON.stringify({
  category: category,
  priority: priority,
  classification_method: 'keyword-based-rules',
  reasoning: 'Detected category "' + category + '" and priority "' + priority + '" based on keyword analysis of: ' + issue.substring(0, 100)
});

// ============================================================
// Create a support ticket
// Input: JSON string with summary, category, priority, customer_email
// Output: JSON with ticket_id and confirmation
// ============================================================
let data = {};
try {
  if (typeof query === 'string') {
    // Try to parse as JSON, otherwise treat as summary text
    try {
      data = JSON.parse(query);
    } catch (e) {
      data = { summary: query };
    }
  } else if (typeof query === 'object' && query !== null) {
    data = query;
  }
} catch (e) {
  data = { summary: String(query || 'Customer support request') };
}

// Generate unique ticket ID
const ticketId = 'TKT-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).substr(2, 4).toUpperCase();
const timestamp = new Date().toISOString();

const ticket = {
  ticket_id: ticketId,
  created_at: timestamp,
  status: 'open',
  summary: data.summary || 'Customer support request',
  category: data.category || 'general',
  priority: data.priority || 'medium',
  customer_email: data.customer_email || data.email || 'anonymous@customer.com',
  description: data.description || data.summary || ''
};

// Attempt to persist in workflow static data (in-memory across executions)
try {
  const staticData = $getWorkflowStaticData('global');
  if (!staticData.tickets) staticData.tickets = [];
  staticData.tickets.push(ticket);
  ticket.total_tickets_in_system = staticData.tickets.length;
} catch (e) {
  // Static data not accessible in this tool context
}

// Response times based on priority
const slaMap = { high: '1 hour', medium: '24 hours', low: '3 business days' };
const sla = slaMap[ticket.priority] || '24 hours';

return JSON.stringify({
  success: true,
  message: 'Ticket ' + ticketId + ' created successfully. Our ' + ticket.category + ' team will respond within ' + sla + '.',
  ticket: ticket
});

// ============================================================
// Analyze job description: extract required skills, experience, seniority
// Input: job description text (via `query`)
// Output: structured JSON with requirements
// ============================================================
const jd = String(query || '').toLowerCase();

const commonSkills = [
  'python', 'javascript', 'typescript', 'java', 'c++', 'c#', 'go', 'golang', 'rust', 'ruby', 'php',
  'react', 'vue', 'angular', 'svelte', 'node.js', 'nodejs', 'next.js', 'nextjs',
  'django', 'flask', 'fastapi', 'express', 'spring', 'rails',
  'postgresql', 'postgres', 'mysql', 'mongodb', 'redis', 'kafka', 'elasticsearch', 'cassandra',
  'aws', 'azure', 'gcp', 'docker', 'kubernetes', 'terraform', 'ansible',
  'machine learning', 'deep learning', 'tensorflow', 'pytorch', 'scikit-learn', 'nlp', 'computer vision',
  'data engineering', 'etl', 'spark', 'airflow', 'snowflake', 'dbt', 'data warehousing',
  'rest api', 'graphql', 'grpc', 'microservices', 'system design',
  'ci/cd', 'jenkins', 'github actions', 'gitlab',
  'html', 'css', 'tailwind', 'bootstrap', 'figma',
  'agile', 'scrum', 'team leadership'
];

const foundSkills = commonSkills.filter(skill => jd.includes(skill));

// Extract minimum experience
let minExperience = 0;
const expMatches = jd.match(/(\d+)\s*\+?\s*(?:year|yr)s?/g);
if (expMatches && expMatches.length > 0) {
  const nums = expMatches.map(m => parseInt(m.match(/\d+/)[0]));
  minExperience = Math.min(...nums);
}

// Seniority detection
let seniority = 'mid';
if (/(senior|lead|principal|staff|architect|manager|head of|director)/i.test(jd)) {
  seniority = 'senior';
} else if (/(junior|entry.level|intern|graduate|fresh)/i.test(jd)) {
  seniority = 'junior';
}

return JSON.stringify({
  extracted_skills: foundSkills,
  min_experience_years: minExperience,
  seniority_level: seniority,
  total_skills_found: foundSkills.length
});

// ============================================================
// Score a candidate against job requirements
// Input: JSON string with { candidate: {...}, requirements: {...} }
// Output: scored evaluation JSON
// ============================================================
let data = {};
try {
  data = typeof query === 'string' ? JSON.parse(query) : query;
} catch (e) {
  return JSON.stringify({
    error: 'Invalid input. Expected JSON string with candidate and requirements objects.',
    received: String(query).substring(0, 200)
  });
}

const candidate = data.candidate || {};
const requirements = data.requirements || {};

// Normalize skills (accept either array or comma-separated string)
const normalizeSkills = (s) => {
  if (Array.isArray(s)) return s.map(x => String(x).toLowerCase().trim());
  if (typeof s === 'string') return s.split(',').map(x => x.toLowerCase().trim()).filter(Boolean);
  return [];
};

const candidateSkills = normalizeSkills(candidate.skills);
const requiredSkills = normalizeSkills(requirements.skills);

// Match skills (with partial matching for variations like 'nodejs' vs 'node.js')
const matchedSkills = requiredSkills.filter(reqSkill =>
  candidateSkills.some(cs =>
    cs.includes(reqSkill) || reqSkill.includes(cs) ||
    cs.replace(/[.\s-]/g, '') === reqSkill.replace(/[.\s-]/g, '')
  )
);
const missingSkills = requiredSkills.filter(s => !matchedSkills.includes(s));

const skillsMatchPercent = requiredSkills.length > 0
  ? Math.round((matchedSkills.length / requiredSkills.length) * 100)
  : 50;

// Experience scoring
const candidateExp = Number(candidate.years_experience) || 0;
const requiredExp = Number(requirements.min_experience) || 0;
const experienceMatch = candidateExp >= requiredExp;
const expScore = experienceMatch
  ? Math.min(100, 70 + (candidateExp - requiredExp) * 5)
  : Math.max(0, 70 - (requiredExp - candidateExp) * 15);

// Weighted total: 60% skills + 30% experience + 10% baseline
const totalScore = Math.round(skillsMatchPercent * 0.6 + expScore * 0.3 + 10);

let recommendation = 'no';
if (totalScore >= 85) recommendation = 'strong_yes';
else if (totalScore >= 70) recommendation = 'yes';
else if (totalScore >= 50) recommendation = 'maybe';

return JSON.stringify({
  candidate_id: candidate.id || 'unknown',
  candidate_name: candidate.name || 'Unknown',
  total_score: totalScore,
  skills_match_percent: skillsMatchPercent,
  matched_skills: matchedSkills,
  missing_skills: missingSkills,
  experience_match: experienceMatch,
  experience_score: expScore,
  recommendation: recommendation,
  reasoning: 'Candidate ' + (candidate.name || 'Unknown') + ' matches ' + matchedSkills.length + '/' + requiredSkills.length + ' required skills (' + skillsMatchPercent + '%). Has ' + candidateExp + ' years experience vs ' + requiredExp + ' required. Overall score: ' + totalScore + '/100. Recommendation: ' + recommendation + '.'
});
